begin;
create extension if not exists pgtap with schema extensions;
select plan(6);
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000007','retrieval@test.invalid');
insert into public.workspaces(id,name) values ('20000000-0000-4000-8000-000000000007','Retrieval');
insert into public.workspace_members values ('20000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000007','owner',now());
create temporary table ids(result jsonb);grant all on ids to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000007","role":"authenticated"}',true);
insert into ids values(public.save_case_revision('20000000-0000-4000-8000-000000000007','{"title":"Canary","template":"product_delivery","outcome":"achieved","problem":"Canary","context":"Team","constraints":"No downtime","approach":"Canary","observedOutcome":"Released","lessons":"Monitor","deliverable":"Feature","changeScope":"Checkout","deploymentConditions":"Rollback","sources":[],"conceptIds":[]}'));
select public.publish_case_revision((select (result->>'revisionId')::uuid from ids),(select jsonb_agg(jsonb_build_object('key',key,'text',value,'embedding',to_jsonb(array_prepend(1::float8,array_fill(0::float8,array[1535]))))) from public.case_revisions,jsonb_each_text(content) where workspace_id='20000000-0000-4000-8000-000000000007' and key in ('problem','context','constraints','approach','observedOutcome','lessons','deliverable','changeScope','deploymentConditions')),'gemini-embedding-2',1536);
select is((select count(*) from public.search_knowledge('20000000-0000-4000-8000-000000000007','canary',array_prepend(1::float8,array_fill(0::float8,array[1535]))::extensions.vector,'method','{}',12,'gemini-embedding-2',9)),9::bigint,'hybrid search reads published active evidence');
select public.save_case_revision('20000000-0000-4000-8000-000000000007',(select content from public.case_revisions where workspace_id='20000000-0000-4000-8000-000000000007' limit 1),(select (result->>'caseId')::uuid from ids));
select is((select count(*) from public.read_knowledge_case('20000000-0000-4000-8000-000000000007',(select (result->>'caseId')::uuid from ids),(select (result->>'revisionId')::uuid from ids),'{}',40)),9::bigint,'pinned revision remains available after edit');
select throws_ok($$select public.expand_knowledge('20000000-0000-4000-8000-000000000007',array['30000000-0000-4000-8000-000000000999'::uuid],array['related_to'],40)$$,'42501',null,'cross-workspace or unavailable seed rejected');
select public.archive_case((select (result->>'caseId')::uuid from ids));
select is((select count(*) from public.search_knowledge('20000000-0000-4000-8000-000000000007','canary',array_prepend(1::float8,array_fill(0::float8,array[1535]))::extensions.vector,'method','{}',12,'gemini-embedding-2',9)),0::bigint,'archive excluded from new retrieval');
select is((select count(*) from public.read_knowledge_case('20000000-0000-4000-8000-000000000007',(select (result->>'caseId')::uuid from ids),(select (result->>'revisionId')::uuid from ids),'{}',40)),0::bigint,'archive during run rejected as new evidence');
select is((select count(*) from public.case_sections where revision_id=(select (result->>'revisionId')::uuid from ids)),9::bigint,'authorized historical source sections remain readable');
select * from finish();rollback;
